script:
frappe
	.require("/assets/payment_core/js/payment_analytics_render.js")
	.then(() => {
		const Renderer = window.PaymentAnalyticsRender;

		const style = document.createElement("style");
		style.textContent = Renderer.style();
		root_element.prepend(style);

		let request_seq = 0;

		function q(sel) {
			return root_element.querySelector(sel);
		}

		function load() {
			const seq = ++request_seq;
			q(".pc-status").textContent = __("Loading") + "...";
			frappe
				.call({
					method: "payment_core.analytics.get_analytics",
					args: { range_key: "30" },
				})
				.then((r) => {
					if (seq !== request_seq) return;
					const data = (r && r.message) || {};
					const currency = data.currency;
					const kpis = data.kpis || {};
					const container = q(".payment-summary");
					container.innerHTML = `
						<div class="payment-kpi-grid">
							${Renderer.kpi_card(__("Gross volume"), Renderer.money(kpis.gross, currency), __("Captured in range"))}
							${Renderer.kpi_card(__("Successful payments"), kpis.successful || 0, __("Completed payments"))}
							${Renderer.kpi_card(__("Customers"), kpis.customers || 0, __("Distinct buyers"))}
							${Renderer.kpi_card(__("Average payment"), Renderer.money(kpis.average, currency), __("Per capture"))}
						</div>
						<div class="payment-chart-grid">
							${Renderer.chart_card(__("Payments volume over time"), "payment-volume-chart")}
							${Renderer.chart_card(__("Payment methods"), "payment-method-chart")}
						</div>`;
					Renderer.draw_charts(container, data, { currency });
					q(".pc-status").textContent = __("Updated");
				})
				.catch(() => {
					if (seq === request_seq) q(".pc-status").textContent = __("Unable to load");
				});
		}

		q("#pc-refresh").addEventListener("click", load);
		load();
	});

style:
.pc-toolbar {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: var(--margin-md);
	padding-bottom: var(--padding-sm);
	font-size: var(--text-sm);
}

.pc-toolbar .pc-status {
	color: var(--text-muted);
}

.pc-toolbar a {
	margin-left: auto;
}
